const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体示意' },
      { kind: 'text', payload: '由静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v 与 g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W / 2;
    var ballR = 24;
    var ballCy = 92;
    var ball = visualSdk.circle(cx, ballCy, ballR);
    var vArrow = visualSdk.arrow(cx + 36, ballCy, cx + 36, ballCy + 118, { headLength: 12, headWidth: 8 });
    var gArrow = visualSdk.arrow(cx - 36, ballCy, cx - 36, ballCy + 118, { headLength: 12, headWidth: 8 });
    var traj = visualSdk.polyline([[cx, ballCy + ballR], [cx, H - 42]]);
    var ground = visualSdk.polyline([[W * 0.22, H - 30], [W * 0.78, H - 30]]);
    return {
      schemaVersion: 1,
      sceneId: 'free-fall-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'traj', commands: traj },
        { id: 'ground', commands: ground },
        { id: 'ball', commands: ball },
        { id: 'vArrow', commands: vArrow },
        { id: 'gArrow', commands: gArrow }
      ],
      root: { type: 'group', children: [
        { type: 'label', text: '自由落体（示意）', x: cx, y: 28, fontSize: 18, fill: '#26354a', textAnchor: 'middle' },
        { type: 'path', pathId: 'traj', stroke: '#8794a5', strokeWidth: 2, strokeDasharray: '6 6' },
        { type: 'path', pathId: 'ground', stroke: '#26354a', strokeWidth: 2 },
        { type: 'path', pathId: 'ball', fill: '#ffffff', stroke: '#26354a', strokeWidth: 3 },
        { type: 'path', pathId: 'vArrow', stroke: '#1f6feb', strokeWidth: 3 },
        { type: 'path', pathId: 'gArrow', stroke: '#d9480f', strokeWidth: 3 },
        { type: 'label', text: 'v', x: cx + 54, y: ballCy + 58, fontSize: 22, fill: '#1f6feb', textAnchor: 'middle', dominantBaseline: 'middle' },
        { type: 'label', text: 'g', x: cx - 54, y: ballCy + 58, fontSize: 22, fill: '#d9480f', textAnchor: 'middle', dominantBaseline: 'middle' },
        { type: 'label', text: '由静止释放', x: cx, y: ballCy - 52, fontSize: 16, fill: '#26354a', textAnchor: 'middle' },
        { type: 'label', text: 'v 与 g 均竖直向下', x: cx, y: H - 8, fontSize: 14, fill: '#26354a', textAnchor: 'middle' }
      ] }
    };
  }
};
